        <el-form-item :label="t('versionStatus')"><el-select v-model="filters.status" clearable :placeholder="t('allStatuses')"><el-option :label="t('active')" value="ACTIVE" /><el-option :label="t('voided')" value="VOID" /></el-select></el-form-item>
        <el-form-item :label="t('filterDate')"><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD" :placeholder="t('anyDate')" clearable /></el-form-item>
