          <p class="hint">{{ t('conversion') }}</p>
        </el-collapse-item></el-collapse>
      </el-form>
      <template #footer><el-button @click="dialog=false">{{ t('cancel') }}</el-button><el-button type="primary" :loading="saving" @click="save">{{ t('save') }}</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup name="BusinessCostPolicies">
const props=defineProps({staffUserId:{type:Number,default:null},embedded:{type:Boolean,default:false}})
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { ElMessage, ElMessageBox } from 'element-plus'
import useUserStore from '@/store/modules/user'
import { getBusinessStaffCostOptions, getBusinessStaffCostPolicies, saveBusinessStaffCostPolicy, deleteBusinessStaffCostPolicy, voidBusinessStaffCostPolicy } from '@/api/business/staff'

const { t } = useI18n({ useScope:'local', messages:{
  'zh-CN':{company:'公司',allCompanies:'全部授权公司',unknownCompany:'未设置公司',personSearch:'搜索姓名或账号',noPeople:'该公司暂无可查看的人员',versionStatus:'版本状态',allStatuses:'全部状态',filterDate:'适用日期',anyDate:'不限日期',resetFilters:'重置筛选',matchingVersions:'显示 {count} / {total} 个成本版本',noMatchingPolicies:'没有符合筛选条件的成本记录，请调整条件或重置筛选。',personName:'人员',region:'国家/地区',CN:'中国',VN:'越南',unknownRegion:'未设置',CNY:'人民币（CNY）',VND:'越南盾（VND）',USD:'美元（USD）',monthlyCost:'月度用人成本',dailyCost:'每日用人成本',hourlyCost:'每小时用人成本',preview:'系统折算',perDay:' / 人天',perHour:' / 小时',advanced:'高级设置：计价方式',missingRegion:'请先在人员管理中设置国家/地区：中国按21.75天、越南按26天折算。',remarkHint:'例如：转正后调整月度用人成本',invalidPeriod:'失效日期不能早于生效日期',invalidRateDay:'一个费率人天须为1至1440分钟',title:'人员成本设置',intro:'填写月度用人成本，系统自动折算日成本和小时成本，用于项目预算与成员工作日成本核算。',boundary:'内部费率不等于员工工资。人员成本按参与工作日计算；已计价日期保留原金额和依据，调整历史金额请在项目核算中登记调整记录。',refresh:'刷新',person:'选择授权范围内的人员',add:'设置用人成本',selectPerson:'先选择人员查看费率历史',forbidden:'没有查看该人员内部费率的授权',empty:'尚未配置成本，相关工作日将显示待完善。',version:'版本',rate:'内部费率',dailyCostColumn:'日成本',period:'生效区间',ongoing:'长期',status:'状态',active:'有效',voided:'已作废',evidence:'依据与历史',action:'操作',delete:'删除',void:'作废',newVersion:'设置用人成本',immutable:'已保存的费率以新版本变更。已确认的成本快照保留原依据；缺失费率补齐后可在核算页重试计价。',mode:'计价单位',MONTHLY:'每月',DAILY:'每人天',HOURLY:'每小时',currency:'币种',unitCost:'内部成本单价',standardDays:'月度标准工作天数',rateDayMinutes:'一个费率人天的分钟数',conversion:'月度成本按人员地区自动折算：中国21.75天，越南26天；换算规则由系统统一维护。',from:'生效日期（含）',to:'失效日期（含，可选）',remark:'调整依据',cancel:'取消',save:'保存新版本',saved:'费率版本已保存',required:'请填写单价、币种、生效日期和调整依据',invalidDays:'请填写月度标准工作天数',deleteConfirm:'删除未生效且未被引用的费率版本？',voidPrompt:'请填写作废原因，已核算历史快照仍会保留',confirm:'确认',done:'处理完成'},
  vi:{company:'Công ty',allCompanies:'Tất cả công ty được phép',unknownCompany:'Chưa thiết lập công ty',personSearch:'Tìm tên hoặc tài khoản',noPeople:'Không có nhân sự được phép xem',versionStatus:'Trạng thái phiên bản',allStatuses:'Tất cả trạng thái',filterDate:'Ngày áp dụng',anyDate:'Không giới hạn ngày',resetFilters:'Đặt lại bộ lọc',matchingVersions:'Hiển thị {count} / {total} phiên bản chi phí',noMatchingPolicies:'Không có đơn giá phù hợp. Hãy đổi hoặc đặt lại bộ lọc.',personName:'Nhân sự',region:'Quốc gia / khu vực',CN:'Trung Quốc',VN:'Việt Nam',unknownRegion:'Chưa thiết lập',CNY:'Nhân dân tệ (CNY)',VND:'Việt Nam đồng (VND)',USD:'Đô la Mỹ (USD)',monthlyCost:'Chi phí nhân sự mỗi tháng',dailyCost:'Chi phí mỗi ngày công',hourlyCost:'Chi phí mỗi giờ',preview:'Quy đổi tự động',perDay:' / ngày công',perHour:' / giờ',advanced:'Nâng cao: cách tính',missingRegion:'Thiết lập quốc gia trong quản lý nhân sự: Trung Quốc 21,75 ngày, Việt Nam 26 ngày.',remarkHint:'Ví dụ: điều chỉnh chi phí khi hết thử việc',invalidPeriod:'Ngày kết thúc không được trước ngày bắt đầu',invalidRateDay:'Một ngày đơn giá phải từ 1 đến 1440 phút',title:'Thiết lập chi phí nhân sự',intro:'Quản lý đơn giá và đơn vị theo ngày hiệu lực để hạch toán công việc đã xác nhận.',boundary:'Đơn giá nội bộ không phải tiền lương. Lịch quyết định năng lực, đơn vị khối lượng quy đổi phút, cơ sở ngày của đơn giá quyết định định giá. Ba phiên bản được lưu riêng.',refresh:'Làm mới',person:'Chọn nhân sự trong phạm vi được phép',add:'Thêm phiên bản đơn giá',selectPerson:'Chọn nhân sự để xem lịch sử đơn giá',forbidden:'Không có quyền xem đơn giá của nhân sự này',empty:'Chưa có đơn giá; công việc đã xác nhận sẽ chờ định giá',version:'Phiên bản',rate:'Đơn giá nội bộ',dailyCostColumn:'Chi phí mỗi ngày',period:'Khoảng hiệu lực',ongoing:'Không giới hạn',status:'Trạng thái',active:'Hiệu lực',voided:'Đã hủy',evidence:'Căn cứ và lịch sử',action:'Thao tác',delete:'Xóa',void:'Hủy hiệu lực',newVersion:'Thêm phiên bản đơn giá nội bộ',immutable:'Thay đổi bằng phiên bản mới. Chi phí đã xác nhận giữ căn cứ cũ; bổ sung đơn giá rồi thử định giá lại trong hạch toán.',mode:'Đơn vị tính',MONTHLY:'Mỗi tháng',DAILY:'Mỗi ngày công',HOURLY:'Mỗi giờ',currency:'Tiền tệ',unitCost:'Đơn giá chi phí nội bộ',standardDays:'Số ngày chuẩn trong tháng',rateDayMinutes:'Số phút trong một ngày đơn giá',conversion:'Chi phí tháng tự quy đổi theo khu vực: Trung Quốc 21,75 ngày, Việt Nam 26 ngày; hệ thống quản lý cơ sở quy đổi.',from:'Ngày bắt đầu (bao gồm)',to:'Ngày kết thúc (tùy chọn)',remark:'Căn cứ điều chỉnh',cancel:'Hủy',save:'Lưu phiên bản mới',saved:'Đã lưu phiên bản đơn giá',required:'Điền đơn giá, tiền tệ, ngày hiệu lực và căn cứ',invalidDays:'Điền số ngày chuẩn trong tháng',deleteConfirm:'Xóa phiên bản chưa có hiệu lực và chưa được tham chiếu?',voidPrompt:'Nhập lý do hủy; ảnh chụp chi phí lịch sử vẫn được giữ',confirm:'Xác nhận',done:'Đã xử lý'}
} })
const route=useRoute(),user=useUserStore(),people=ref([]),policies=ref([]),selectedUserId=ref(null),loading=ref(false),dialog=ref(false),saving=ref(false),retiring=ref(null),form=reactive({}),advanced=ref([])
const filters=reactive({company:'',status:'',date:null})
const companyKey=person=>person.companyDeptId!=null?String(person.companyDeptId):person.companyName||'__unassigned__'
const companies=computed(()=>Array.from(new Map(people.value.map(person=>[companyKey(person),{key:companyKey(person),name:person.companyName||t('unknownCompany')}])).values()).sort((a,b)=>a.name.localeCompare(b.name)))
const filteredPeople=computed(()=>props.embedded||!filters.company?people.value:people.value.filter(person=>companyKey(person)===filters.company))
const personLabel=person=>`${person.nickName || person.userName}${person.userName && person.userName!==person.nickName ? ` (${person.userName})` : ''} · ${person.companyName || t('unknownCompany')}`
const filteredPolicies=computed(()=>policies.value.filter(policy=>(!filters.status||policy.status===filters.status)&&(!filters.date||String(policy.effectiveFrom).slice(0,10)<=filters.date&&(!policy.effectiveTo||String(policy.effectiveTo).slice(0,10)>=filters.date))))
const costDateColors=[
  {background:'#dff4ec',border:'#2f9a78',text:'#17634d'},
  {background:'#e5effd',border:'#4b82cf',text:'#2f5f9f'},
  {background:'#fff0d5',border:'#d28a20',text:'#85570f'},
  {background:'#f2e8fb',border:'#9661c2',text:'#693d91'},
  {background:'#fde7e9',border:'#d15b65',text:'#913841'},
  {background:'#e6f1f2',border:'#43878d',text:'#275f64'}
]
const activeCostPolicies=computed(()=>policies.value.filter(policy=>policy.status==='ACTIVE').slice().sort((a,b)=>Number(a.policyVersion)-Number(b.policyVersion)))
const hasCostOverlap=computed(()=>activeCostPolicies.value.some((policy,index)=>activeCostPolicies.value.slice(index+1).some(other=>{const from=normalizedCostDate(policy.effectiveFrom),to=normalizedCostDate(policy.effectiveTo)||'9999-12-31',otherFrom=normalizedCostDate(other.effectiveFrom),otherTo=normalizedCostDate(other.effectiveTo)||'9999-12-31';return from&&otherFrom&&from<=otherTo&&otherFrom<=to})))
async function companyChanged(){if(!filteredPeople.value.some(person=>person.userId===selectedUserId.value)){selectedUserId.value=filteredPeople.value[0]?.userId||null;await loadPolicies()}}
function resetFilters(){filters.company='';filters.status='';filters.date=null}
const hasCostPermission=computed(()=>user.permissions.includes('*:*:*')||user.permissions.includes('business:staff:cost')||props.embedded&&user.permissions.includes('business:staff:list'))
const selectedPerson=computed(()=>people.value.find(p=>p.userId===selectedUserId.value))
const rawCostVisible=computed(()=>hasCostPermission.value&&selectedPerson.value?.rawCostVisible===true)
const canManage=computed(()=>rawCostVisible.value&&selectedPerson.value?.canManageCost===true)
const modeLabel=mode=>['MONTHLY','DAILY','HOURLY'].includes(mode)?t(mode):mode
const money=value=>value==null?'—':Number(value).toLocaleString(undefined,{maximumFractionDigits:4})
function normalizedCostDate(value){if(!value)return null;if(value instanceof Date&&!Number.isNaN(value.getTime()))return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`;const match=String(value).match(/^\d{4}-\d{2}-\d{2}/);return match?match[0]:null}
function costCellDate(cell){return cell?.date||cell?.dayjs?.toDate?.()||cell?.day||null}
function costPoliciesForDate(day){const date=normalizedCostDate(day);if(!date)return [];return activeCostPolicies.value.filter(policy=>{const from=normalizedCostDate(policy.effectiveFrom),to=normalizedCostDate(policy.effectiveTo);return !!from&&date>=from&&(!to||date<=to)})}
function costDateClass(day){const matches=costPoliciesForDate(day);return {'has-cost':matches.length>0,'has-overlap':matches.length>1}}
function costPolicyColor(policy){const index=activeCostPolicies.value.indexOf(policy);return costDateColors[(index<0?0:index)%costDateColors.length]}
function costDateStyle(day){const matches=costPoliciesForDate(day);if(!matches.length)return {};const colors=matches.map(costPolicyColor);const background=colors.length===1?colors[0].background:`linear-gradient(135deg, ${colors.map((color,index)=>`${color.background} ${index*100/colors.length}% ${(index+1)*100/colors.length}%`).join(', ')})`;return {'--cost-date-background':background,'--cost-date-border':colors[0].border,'--cost-date-text':colors[0].text}}
function costDateTitle(day){const matches=costPoliciesForDate(day);return matches.map(policy=>`v${policy.policyVersion}：${money(policy.unitCost)} ${policy.currency} · ${modeLabel(policy.costMode)}（${policy.effectiveFrom} 至 ${policy.effectiveTo||t('ongoing')}）`).join('\n')}
function costPolicySwatchStyle(index){const color=costDateColors[index%costDateColors.length];return {background:color.background,borderColor:color.border}}
function policyDailyCostText(policy){
  if(policy.unitCost==null||policy.unitCost==='')return '—'
  const unitCost=Number(policy.unitCost),standardDays=Number(policy.standardWorkDays)
  if(!Number.isFinite(unitCost)||unitCost<0)return '—'
  // Match member-day accounting, using each historical version's own monthly divisor.
  const dailyCost=policy.costMode==='MONTHLY'?(Number.isFinite(standardDays)&&standardDays>0?unitCost/standardDays:null):policy.costMode==='DAILY'?unitCost:policy.costMode==='HOURLY'?unitCost*8:null
  return dailyCost==null||!Number.isFinite(dailyCost)?'—':`${dailyCost.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})} ${policy.currency || ''}`.trim()
}
const defaultStandardDays=computed(()=>({CN:21.75,VN:26}[selectedPerson.value?.countryRegion]??null))
const regionName=computed(()=>['CN','VN'].includes(selectedPerson.value?.countryRegion)?t(selectedPerson.value.countryRegion):selectedPerson.value?.countryRegion||t('unknownRegion'))
const amountLabel=computed(()=>t(({MONTHLY:'monthlyCost',DAILY:'dailyCost',HOURLY:'hourlyCost'})[form.costMode]||'unitCost'))
const amountText=value=>value==null||!Number.isFinite(value)?'—':Number(value).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:4})
const dailyRate=computed(()=>form.unitCost==null?null:form.costMode==='MONTHLY'?(form.standardWorkDays>0?Number(form.unitCost)/form.standardWorkDays:null):form.costMode==='DAILY'?Number(form.unitCost):null)
const costPreview=computed(()=>form.costMode==='HOURLY'?`${amountText(form.unitCost)} ${form.currency}${t('perHour')}`:form.costMode==='MONTHLY'?`${amountText(form.unitCost)} ÷ ${form.standardWorkDays||'—'} = ${amountText(dailyRate.value)} ${form.currency}${t('perDay')}`:`${amountText(dailyRate.value)} ${form.currency}${t('perDay')}`)
const hourlyPreview=computed(()=>form.costMode==='HOURLY'?'':`${amountText(dailyRate.value!=null&&form.rateMinutesPerDay>0?dailyRate.value*60/form.rateMinutesPerDay:null)} ${form.currency}${t('perHour')}`)
const disableEndDate=date=>!!form.effectiveFrom&&date.getTime()<new Date(`${form.effectiveFrom}T00:00:00`).getTime()
const today=()=>{const date=new Date();return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
let sequence=0
async function loadPeople(){if(!hasCostPermission.value)return;loading.value=true;try{people.value=(await getBusinessStaffCostOptions()).data||[];if(filters.company&&!companies.value.some(company=>company.key===filters.company))filters.company='';const requested=props.staffUserId||selectedUserId.value||Number(route.query.userId);if(filteredPeople.value.some(p=>p.userId===requested))selectedUserId.value=requested;else selectedUserId.value=props.embedded?requested:filteredPeople.value[0]?.userId||null;await loadPolicies()}finally{loading.value=false}}
async function loadPolicies(){const current=++sequence;policies.value=[];if(!rawCostVisible.value){loading.value=false;return}loading.value=true;try{const response=await getBusinessStaffCostPolicies(selectedUserId.value);if(current===sequence)policies.value=response.data||[]}finally{if(current===sequence)loading.value=false}}
function openCreate(){Object.assign(form,{userId:selectedUserId.value,costMode:'MONTHLY',unitCost:null,currency:'CNY',standardWorkDays:defaultStandardDays.value,rateMinutesPerDay:480,effectiveFrom:today(),effectiveTo:null,remark:''});advanced.value=[];dialog.value=true}
async function save(){if(!canManage.value||saving.value)return;const body={...form,currency:form.currency?.trim().toUpperCase()};if(body.unitCost==null||!['CNY','VND','USD'].includes(body.currency)||!body.effectiveFrom||!body.remark?.trim())return ElMessage.warning(t('required'));if(body.costMode==='MONTHLY'&&!defaultStandardDays.value)return ElMessage.warning(t('missingRegion'));delete body.standardWorkDays;delete body.rateMinutesPerDay;if(body.effectiveTo&&body.effectiveTo<body.effectiveFrom)return ElMessage.warning(t('invalidPeriod'));body.remark=body.remark.trim();saving.value=true;try{await saveBusinessStaffCostPolicy(body);dialog.value=false;ElMessage.success(t('saved'));await loadPolicies()}finally{saving.value=false}}
const canDelete=row=>row.status==='ACTIVE'&&row.effectiveFrom>today()&&!(Number(row.referenceCount)>0)
async function retire(row){if(!canManage.value)return;try{if(canDelete(row)){await ElMessageBox.confirm(t('deleteConfirm'),t('confirm'),{type:'warning',confirmButtonText:t('confirm'),cancelButtonText:t('cancel')});retiring.value=row.policyId;await deleteBusinessStaffCostPolicy(row.policyId)}else{const {value}=await ElMessageBox.prompt(t('voidPrompt'),t('void'),{inputType:'textarea',inputValidator:v=>!!v?.trim()&&v.length<=500,confirmButtonText:t('confirm'),cancelButtonText:t('cancel')});retiring.value=row.policyId;await voidBusinessStaffCostPolicy(row.policyId,value.trim())}ElMessage.success(t('done'));await loadPolicies()}catch(error){if(!['cancel','close'].includes(error))throw error}finally{retiring.value=null}}
onMounted(loadPeople)
</script>

